function nacci(maxValue, returnSequence = false){
	let fib;
	let nFib = 2;
	let pFib = 1;
	let count = 0;
	if (returnSequence === false){
		fib = 1;
		while(count<=maxValue-2){
			nFib += fib;
			pFib = fib;
			fib = nFib - pFib;
			count++;
		}
	} else if (returnSequence === true){
		fib = [1];
		while(count<=maxValue-2){
			nFib += fib[count];
			pFib = fib[count];
			fib.push(nFib - pFib);
			count++;
		}
	}
	return fib;
}



