function getLine(x1, y1, x2, y2, res = 1, drawLine = false) {
	let points = [];
	let xTrans, yTrans;
	let rev = false;
	let isSteep = false;
	if (abs(y2 - y1) > abs(x2 - x1)) {
		isSteep = true;
	} else {
		isSteep = false;
	}
	if (isSteep === true) {
		xTrans = x1;
		x1 = y1;
		y1 = xTrans;
		xTrans = x2;
		x2 = y2;
		y2 = xTrans;
	}
	if (x1 > x2) {
		xTrans = x1;
		x1 = x2;
		x2 = xTrans;
		yTrans = y1;
		y1 = y2;
		y2 = yTrans;
		rev = true;
	}
	let deltax = (x2 - x1);
	let deltay = Math.abs(y2 - y1);
	let error = Math.sign(deltax)*inc(Math.abs(deltax) / 2, res, "CEIL");
	let y = y1;
	let yStep;
	if (y1 < y2) {
		yStep = res;
	} else {
		yStep = -res;
	}
	for (let x = 0; x < Math.abs(x2 - x1) + res; x += res) {
		if (isSteep === true) {
			points.push([y, x + x1]);
		} else {
			points.push([x + x1, y]);
		}
		error -= deltay;
		if (error <= 0) {
			y += yStep;
			error += deltax;
		}
	}
	if (rev === true) {
		points.reverse();
	}
	if (drawLine === true) {
		for (let p of points) {
			point(p[0], p[1]);
		}
	}
	return points;
}
/**Polygon
//
//  description: A class from which the user can create regular polygons of any number of sides.
//  static methods:
//    Polygon.calcAngle(number of sides, angle mode): for determining the interior angled of the polygon, given the number of sides.
//  constructor: (x position, y position, number of sides, radius, p5color, ['DEGREES', 'RADIANS'])
//  properties:
//    x position
//    y position
//    radius length
//    angle type
//    interior angle
//    color
//  methods:
//     setColor(p5color): changes the polygon object's color property to the specified p5color.
//     convertType(): toggles the polygon object's angle mode property between 'DEGREES' and 'RADIANS'.
//     show(): draws the polygon.
//
//
*/
class Polygon {
	static calcAngle(n, type=this.type) {
		if (type == 'RADIANS') {
			angleMode(RADIANS);
			return (Math.PI * 2) / n;
		} else if (type == 'DEGREES') {
			angleMode(DEGREES);
			return 360 / n;
		}
	}
	constructor(x, y, npoints, radius=20, col=rCol(), type='DEGREES') {
		this.x = x;
		this.y = y;
		this.radius = radius;
		this.type = type;
		this.angle = Polygon.calcAngle(npoints, type);
		if (col instanceof p5.Color) {
			this.shade = col;
		} else if (col === typeof Number || col === typeof String) {
			this.shade = color(col);
		}
	}
	setColor(p5color) {
		this.shade = p5color;
		return this.shade;
	}
	convertType() {
		if (this.type == 'RADIANS') {
			this.type = 'DEGREES';
			angleMode(DEGREES);
			this.angle = Polygon.calcAngle((Math.PI * 2) / this.angle)
		} else if (type == 'DEGREES') {
			this.type = 'RADIANS';
			angleMode(RADIANS);
			this.angle = Polygon.calcAngle(360 / this.angle)
		}
		return this.type;
	}
	show() {
		let fullCircle;
		if (this.type == 'RADIANS') {
			fullCircle = Math.PI * 2;
		} else if (this.type == 'DEGREES') {
			fullCircle = 360;
		}
		fill(this.shade);
		beginShape();
		for (let a = 0; a < fullCircle; a += this.angle) {
			let sx = this.x + Math.cos(a) * this.radius;
			let sy = this.y + Math.sin(a) * this.radius;
			vertex(sx, sy);
		}
		endShape(CLOSE);
	}
}

class ObjectArray {
	constructor(objectClass, container=[]) {
		this.class = objectClass;
